package cache

// Storage описывает низкоуровневый контракт для движков хранения данных кэша (Low-Level Storage Contract).
//
// Инкапсулирует логику работы с сырыми байтовыми массивами ([]byte), абстрагируя оркестратор Manager
// от конкретной внутренней топологии хранения: будь то плоская хэш-мапа (RawStorage) или
// горизонтально масштабируемая сегментированная структура (ShardStorage) с защитой от Mutex Contention.
type Storage[K comparable] interface {
	// Get извлекает сырой байтовый payload по его ключу под защитой внутренних механизмов синхронизации.
	Get(key K) (value []byte, ok bool)

	// Set атомарно сохраняет или перезаписывает бинарный payload для указанного ключа.
	Set(key K, b []byte)

	// Delete принудительно стирает ключ и очищает связанные индексы контроллера вытеснения.
	Delete(key K)

	// Range выполняет потоковый конкурентно-безопасный обход всех элементов хранилища.
	// Если переданная функция-колбек fn возвращает false, цикл итерации мгновенно прерывается.
	Range(fn func(key K, value []byte) bool)

	// Has проверяет фактическое наличие ключа в памяти по быстрым read-локам без изменения приоритетов вытеснения.
	Has(key K) bool

	// Len возвращает текущее суммарное количество элементов, удерживаемых в текущем сегменте памяти.
	Len() int

	// Clear осуществляет полный сброс памяти хранилища и обнуление связанных структур.
	Clear()
}
